#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <queue>
#include <map>
using namespace std;

int main(){
    vector<vector<double>> a={{3,2,-1,1},{2,-2,4,-2},{-1,0.5,-1,0}};
    int n=3;
    for(int k=0;k<n;k++){
        int p=k;
        for(int i=k+1;i<n;i++)if(fabs(a[i][k])>fabs(a[p][k]))p=i;
        if(fabs(a[p][k])<1e-12)return 1;
        swap(a[p],a[k]);
        for(int i=k+1;i<n;i++){
            double factor=a[i][k]/a[k][k];
            for(int j=k;j<=n;j++)a[i][j]-=factor*a[k][j];
        }
    }
    vector<double> x(n,0);
    for(int i=n-1;i>=0;i--){
        double value=a[i][n];
        for(int j=i+1;j<n;j++)value-=a[i][j]*x[j];
        x[i]=value/a[i][i];
    }
    for(double v:x)cout<<fixed<<setprecision(6)<<v<<"\n";
    return 0;
}

