#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <queue>
#include <map>
using namespace std;

int main(){
    vector<double> losses={1,2,1,0,1,3,2,1,4,2,1,0,2,3,1,2,4,1,3,10};
    sort(losses.begin(),losses.end());
    double confidence=0.95,tailMass=1-confidence;
    int tailCount=int(losses.size()*tailMass+1e-9);
    if(tailCount<=0)return 1;
    double es=0;
    for(int i=int(losses.size())-tailCount;i<int(losses.size());i++)es+=losses[i]/tailCount;
    cout<<fixed<<setprecision(6)<<es<<"\n";
    return 0;
}
